// User-supplied filename is stored in 'filename'
const safeFilename = path.normalize(filename);

// Ensure the file is within the intended directory
if (!safeFilename.startsWith(__dirname)) {
  throw new Error('Invalid filename');
}

// Remove any '..' or '.' characters from the filename
const sanitizedFilename = safeFilename.replace(/\/[^/]+\/|\/./g, '');

// Construct the final filepath using the sanitized filename
const filePath = path.join(__dirname, sanitizedFilename);
```
